export const Escena:React.FC=()=>{
 const{s}=useS();const cuts=[0,en('dieciocho'),en('sinagoga'),A[1],en('jefe'),A[2],A[3],A[4]];
 let n=0;for(let j=1;j<cuts.length;j++)if(s>=cuts[j])n=j;
 const half=.55;let content:React.ReactNode=<Visual n={n}/>;
 for(let j=1;j<cuts.length;j++)if(s>=cuts[j]-half&&s<cuts[j]+half){const f=q(s,cuts[j]-half,cuts[j]+half);content=<><AbsoluteFill style={{opacity:1-f}}><Visual n={j-1}/></AbsoluteFill><AbsoluteFill style={{opacity:f}}><Visual n={j}/></AbsoluteFill><AbsoluteFill style={{background:'radial-gradient(ellipse at 35% 35%,#ffe9b5,transparent 75%)',opacity:Math.sin(f*Math.PI)*.16}}/></>;}
